BEGIN;
DO $$
DECLARE v_owner uuid:=gen_random_uuid(); v_finance uuid:=gen_random_uuid(); v_user uuid:=gen_random_uuid(); v_session uuid:=gen_random_uuid(); v_finance_session uuid:=gen_random_uuid(); v_user_session uuid:=gen_random_uuid(); v_business uuid; v_second uuid; v_version uuid; v_ticket uuid; v_notification uuid; v_role uuid; v_assign uuid; v_feature uuid; v_firm uuid; x jsonb; k text; denied boolean; n bigint; previous_prices bigint; previous_limits bigint;
BEGIN
 INSERT INTO auth.users(id,email) VALUES(v_owner,'operations-'||v_owner||'@example.invalid'),(v_finance,'finance-'||v_finance||'@example.invalid'),(v_user,'customer-'||v_user||'@example.invalid');
 INSERT INTO auth.sessions(id,user_id,created_at,updated_at) VALUES(v_session,v_owner,now(),now()),(v_finance_session,v_finance,now(),now()),(v_user_session,v_user,now(),now());
 INSERT INTO public.platform_roles(user_id,role) VALUES(v_owner,'platform_owner'),(v_finance,'platform_finance');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_owner,'session_id',v_session,'aal','aal2','iat',floor(extract(epoch from now())))::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 x:=public.platform_mutate('business.create',NULL,jsonb_build_object('name','Operations fixture','owner_id',v_user,'country_code','GB','base_currency','GBP','fiscal_year_end_month',12,'fiscal_year_end_day',31,'timezone','Europe/London'),'Provision fixture');v_business:=(x->>'id')::uuid;
 x:=public.platform_mutate('business.create',NULL,jsonb_build_object('name','Second operations fixture','owner_id',v_user,'country_code','IN','base_currency','INR','fiscal_year_end_month',3,'fiscal_year_end_day',31,'timezone','Asia/Kolkata'),'Provision second fixture');v_second:=(x->>'id')::uuid;
 x:=public.platform_mutate('member.assign',null,jsonb_build_object('company_id',v_business,'user_id',v_finance,'role','accountant'),'Assign business accountant');
 x:=public.platform_details('businesses',v_business); IF jsonb_array_length(x->'members')<>2 THEN RAISE EXCEPTION 'Business detail membership missing'; END IF;
 x:=public.platform_details('users',v_user); IF jsonb_array_length(x->'businesses')<>2 THEN RAISE EXCEPTION 'User detail memberships missing'; END IF;
 x:=public.platform_mutate('firm.save',NULL,jsonb_build_object('name','Operations test firm'),'Create test firm');v_firm:=(x->>'id')::uuid;
 x:=public.platform_mutate('firm.member',NULL,jsonb_build_object('firm_id',v_firm,'user_id',v_user,'role','member'),'Assign firm member');
 x:=public.platform_details('firms',v_firm);IF jsonb_array_length(x->'members')<>1 THEN RAISE EXCEPTION 'Firm details missing'; END IF;
 x:=public.platform_bulk_business(ARRAY[v_business,v_second],'suspended','Bulk suspend test businesses');
 x:=public.platform_bulk_business(ARRAY[v_business,v_second],'active','Bulk reactivate test businesses');
 denied:=false;BEGIN x:=public.platform_bulk_business(ARRAY[v_business,gen_random_uuid()],'suspended','Bulk rollback on missing target');EXCEPTION WHEN raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Bulk update accepted missing target';END IF;
 EXECUTE 'RESET ROLE';
 IF EXISTS(SELECT 1 FROM public.platform_tenant_controls WHERE company_id=v_business AND status<>'active') THEN RAISE EXCEPTION 'Bulk failure did not roll back'; END IF;
 EXECUTE 'SET LOCAL ROLE authenticated';
 x:=public.platform_mutate('business.update',v_business,jsonb_build_object('status','archived'),'Archive fixture');
 EXECUTE 'RESET ROLE';IF NOT EXISTS(SELECT 1 FROM public.companies WHERE id=v_business AND archived_at IS NOT NULL) THEN RAISE EXCEPTION 'Archive flag missing'; END IF; EXECUTE 'SET LOCAL ROLE authenticated';
 x:=public.platform_mutate('business.update',v_business,jsonb_build_object('status','active'),'Restore fixture');
 FOREACH k IN ARRAY ARRAY['accounting','features','integrations','api','support','notifications'] LOOP
 x:=public.platform_mutate('record.save',null,jsonb_build_object('kind',k,'name',CASE WHEN k='features' THEN 'sales' ELSE 'Operations record '||k||v_user END,'company_id',v_business,'status',CASE WHEN k='support' THEN 'open' WHEN k IN ('integrations','api') THEN 'draft' ELSE 'active' END,'document',CASE WHEN k='notifications' THEN jsonb_build_object('message','Fixture announcement') ELSE '{}'::jsonb END),'Save operational record');
 IF k='features' THEN v_feature:=(x->>'id')::uuid; END IF;
 END LOOP;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_user,'session_id',v_user_session,'aal','aal1','iat',floor(extract(epoch from now())))::text,true);
 x:=public.platform_announcements(v_business);IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(x) a WHERE a->>'message'='Fixture announcement') THEN RAISE EXCEPTION 'Published announcement not delivered'; END IF;
 IF NOT public.has_company_permission(v_business,'sales.draft') THEN RAISE EXCEPTION 'Enabled module denied'; END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_owner,'session_id',v_session,'aal','aal2','iat',floor(extract(epoch from now())))::text,true);
 x:=public.platform_mutate('record.save',v_feature,jsonb_build_object('kind','features','name','sales','company_id',v_business,'status','disabled','version',1,'document','{}'::jsonb),'Disable sales module');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_user,'session_id',v_user_session,'aal','aal1','iat',floor(extract(epoch from now())))::text,true);
 IF public.has_company_permission(v_business,'sales.draft') OR NOT public.has_company_permission(v_business,'sales.view') THEN RAISE EXCEPTION 'Module write restriction or history access failed'; END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_owner,'session_id',v_session,'aal','aal2','iat',floor(extract(epoch from now())))::text,true);
 x:=public.platform_mutate('record.save',v_feature,jsonb_build_object('kind','features','name','sales','company_id',v_business,'status','active','version',2,'document','{}'::jsonb),'Enable sales module');
 x:=public.platform_mutate('user.update',v_user,jsonb_build_object('status','active','require_mfa',true,'full_name','Fixture updated user'),'Require customer MFA');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_user,'session_id',v_user_session,'aal','aal1','iat',floor(extract(epoch from now())))::text,true);
 IF public.is_company_member(v_business) THEN RAISE EXCEPTION 'Required MFA was bypassed'; END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_user,'session_id',v_user_session,'aal','aal2','iat',floor(extract(epoch from now())))::text,true);
 IF NOT public.is_company_member(v_business) THEN RAISE EXCEPTION 'Customer MFA session denied'; END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_owner,'session_id',v_session,'aal','aal2','iat',floor(extract(epoch from now())))::text,true);
 x:=public.platform_mutate('role.save',null,jsonb_build_object('name','Fixture firm scoped reviewer','scope','firm','permissions',jsonb_build_array('company.view','accounting.view','reports.view','sales.draft')),'Create firm scoped role');v_role:=(x->>'id')::uuid;
 x:=public.platform_mutate('role.assign',null,jsonb_build_object('role_id',v_role,'user_id',v_finance,'scope_id',v_firm),'Assign scoped reviewer');
 x:=public.platform_mutate('firm.member',null,jsonb_build_object('firm_id',v_firm,'user_id',v_finance,'role','admin'),'Link finance to test firm');
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claims','{}',true);
 INSERT INTO public.firm_client_links(firm_id,company_id,access_level) VALUES(v_firm,v_second,'view');
 SELECT count(*) INTO previous_prices FROM public.plan_prices p JOIN public.plan_versions v ON v.id=p.version_id WHERE v.plan_code='growth' AND v.status='published';
 SELECT count(*) INTO previous_limits FROM public.plan_version_limits p JOIN public.plan_versions v ON v.id=p.version_id WHERE v.plan_code='growth' AND v.status='published';
 EXECUTE 'SET LOCAL ROLE authenticated';
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_finance,'session_id',v_finance_session,'aal','aal2','iat',floor(extract(epoch from now())))::text,true);
 IF NOT public.has_company_permission(v_second,'reports.view') OR public.has_company_permission(v_second,'sales.draft') THEN RAISE EXCEPTION 'Firm view link did not cap permissions'; END IF;
 denied:=false;BEGIN UPDATE public.firm_client_links SET access_level='full' WHERE firm_id=v_firm AND company_id=v_second;EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Firm admin escalated client access without business authorization';END IF;
 x:=public.platform_company_context();IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(x) a WHERE a->>'id'=v_second::text AND (a->'permissions') ? 'reports.view' AND NOT (a->'permissions') ? 'sales.draft') THEN RAISE EXCEPTION 'Scoped company navigation or effective permission hints failed';END IF;
 x:=public.platform_price_action('draft',jsonb_build_object('planCode','growth','currency','USD','interval','month','amountMinor',3100),'Draft fixture price');v_version:=(x->>'versionId')::uuid;
 denied:=false;BEGIN x:=public.platform_price_action('publish',jsonb_build_object('versionId',v_version),'Unauthorized finance publication');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Finance published a price';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_owner,'session_id',v_session,'aal','aal2','iat',floor(extract(epoch from now())))::text,true);
 x:=public.platform_price_action('publish',jsonb_build_object('versionId',v_version),'Publish fixture price atomically');
 x:=public.platform_price_action('rollback',jsonb_build_object('planCode','growth'),'Roll back fixture publication');
 x:=public.platform_mutate('role.save',null,jsonb_build_object('name','Fixture create-only operator','scope','platform','permissions',jsonb_build_array('businesses.view','businesses.create')),'Define create-only permission');v_role:=(x->>'id')::uuid;
 x:=public.platform_mutate('role.assign',null,jsonb_build_object('role_id',v_role,'user_id',v_finance),'Assign create-only operator');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_finance,'session_id',v_finance_session,'aal','aal2','iat',floor(extract(epoch from now())))::text,true);
 x:=public.platform_context();IF NOT (x->'permissions') ? 'businesses.create' OR (x->'permissions') ? 'businesses.edit' THEN RAISE EXCEPTION 'Individual action capabilities are incorrect';END IF;
 x:=public.platform_mutate('business.create',null,jsonb_build_object('name','Create-only fixture','owner_id',v_user,'country_code','US','base_currency','USD','fiscal_year_end_month',12,'fiscal_year_end_day',31,'timezone','America/New_York'),'Create without edit permission');
 denied:=false;BEGIN x:=public.platform_mutate('business.update',v_business,jsonb_build_object('status','suspended'),'Denied edit action');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Create-only role edited a business';END IF;
 denied:=false;BEGIN x:=public.platform_export('businesses');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'View permission allowed export';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_owner,'session_id',v_session,'aal','aal2','iat',floor(extract(epoch from now())))::text,true);
 x:=public.platform_mutate('role.save',v_role,jsonb_build_object('name','Fixture create-only operator','scope','platform','permissions',jsonb_build_array('businesses.view','businesses.create','businesses.export')),'Grant explicit export permission');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_finance,'session_id',v_finance_session,'aal','aal2','iat',floor(extract(epoch from now())))::text,true);
 x:=public.platform_export('businesses');IF NOT x ? 'rows' THEN RAISE EXCEPTION 'Authorized export failed';END IF;
 EXECUTE 'RESET ROLE';
 IF (SELECT count(*) FROM public.plan_prices WHERE version_id=v_version)<>previous_prices THEN RAISE EXCEPTION 'Draft lost other currencies or intervals';END IF;
 IF (SELECT count(*) FROM public.plan_version_limits WHERE version_id=v_version)<>previous_limits THEN RAISE EXCEPTION 'Draft lost subscription limits';END IF;
 IF (SELECT count(*) FROM public.plan_versions WHERE plan_code='growth' AND status='published')<>1 THEN RAISE EXCEPTION 'Price publication invariant failed';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.company_members WHERE company_id=v_business AND user_id=v_user AND role='owner') THEN RAISE EXCEPTION 'Financial ownership lost';END IF;
END $$;
ROLLBACK;
SELECT 'PASS: provisioning, assignments, related details, bulk atomic rollback, archive/reactivation, record workflows, announcement delivery, module access, mandatory user MFA, firm scope caps and transactional billing with preserved entitlements; fixtures rolled back' AS result;
